67| <body>
68| <div id="wrap">
69|   <div id="hud">
70|     <div id="tally">Pops: 0</div>
71|     <button id="clearBtn">Clear Table</button>
72|   </div>
73|   <canvas id="game"></canvas>
74| </div>
75| <script>
76| const CARTRIDGE = {
77|   send(type, payload = {}) {
78|     window.parent.postMessage(
79|       { source: "cartridge", v: 1, type, payload },
80|       "*",
81|     );
82|   },
83| };
84| </script>
85| <script>
86| (function() {
87|   const canvas = document.getElementById("game");
88|   const ctx = canvas.getContext("2d");
89|   const tallyEl = document.getElementById("tally");
90|   const clearBtn = document.getElementById("clearBtn");
91| 
92|   let dpr = window.devicePixelRatio || 1;
93|   let W = 0, H = 0;
94| 
95|   function resize() {
96|     W = window.innerWidth;
97|     H = window.innerHeight;
98|     dpr = window.devicePixelRatio || 1;
99|     canvas.width = Math.floor(W * dpr);
100|     canvas.height = Math.floor(H * dpr);
101|     canvas.style.width = W + "px";
102|     canvas.style.height = H + "px";
103|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
104|   }
105|   window.addEventListener("resize", resize);
106|   resize();
107| 
108|   // seeded jitter helper for paper-cut edges
109|   function seededRand(seed) {
110|     let s = seed;
111|     return function() {
112|       s = (s * 9301 + 49297) % 233280;
113|       return s / 233280;
114|     };
115|   }
116| 
117|   const PALETTE = {
118|     background: "#f4ecd8",
119|     layer: "#e07a5f",
120|     accent: "#3d405b",
121|     highlight: "#81b29a"
122|   };
123| 
124|   const bubbleColors = [PALETTE.layer, PALETTE.highlight, PALETTE.accent];
125| 
126|   let running = false;
127|   let paused = false;
128|   let tally = 0;
129|   const bubbles = [];
130|   let bubbleId = 0;
131|   const pops = []; // pop animations
132| 
133|   const MAX_BUBBLES = 9;
134| 
135|   function rand(min, max) {
136|     return min + Math.random() * (max - min);
137|   }
138| 
139|   function spawnBubble() {
140|     const r = rand(28, 48);
141|     const x = rand(r + 10, Math.max(r + 20, W - r - 10));
142|     const y = H + r + rand(0, 200);
143|     const speed = rand(0.4, 1.0);
144|     const wobbleSeed = Math.floor(rand(1, 99999));
145|     const color = bubbleColors[Math.floor(rand(0, bubbleColors.length))];
146|     bubbles.push({
147|       id: bubbleId++,
148|       x, y, r,
149|       speed,
150|       color,
151|       wobblePhase: rand(0, Math.PI * 2),
152|       seed: wobbleSeed
153|     });
154|   }
155| 
156|   function ensureBubbles() {
157|     while (bubbles.length < MAX_BUBBLES) {
158|       spawnBubble();
159|     }
160|   }
161| 
162|   // clearTable is THE single function that resets everything:
163|   // clears pieces, zeroes tally, sends score, redraws.
164|   // It is called both by the host "reset" command and by the
165|   // visible Clear Table button. It also returns the toy to the
166|   // pre-start title screen, matching the toy-box "hard reset" contract.
167|   function clearTable() {
168|     running = false;
169|     bubbles.length = 0;
170|     pops.length = 0;
171|     tally = 0;
172|     tallyEl.textContent = "Pops: 0";
173|     CARTRIDGE.send("score", { value: 0 });
174|     draw();
175|   }
176| 
177|   clearBtn.addEventListener("click", clearTable);
178| 
179|   window.addEventListener("message", (event) => {
180|     const data = event.data;
181|     if (!data || data.source !== "cartridge-host") return;
182|     if (data.type === "pause") paused = true;
183|     if (data.type === "resume") paused = false;
184|     if (data.type === "reset") clearTable();
185|   });
186| 
187|   function popBubble(b) {
188|     bubbles.splice(bubbles.indexOf(b), 1);
189|     tally += 1;
190|     tallyEl.textContent = "Pops: " + tally;
191|     CARTRIDGE.send("score", { value: tally });
192|     pops.push({ x: b.x, y: b.y, r: b.r, t: 0, color: b.color });
193|   }
194| 
195|   function hitTest(px, py) {
196|     for (let i = bubbles.length - 1; i >= 0; i--) {
197|       const b = bubbles[i];
198|       const dx = px - b.x;
199|       const dy = py - b.y;
200|       if (dx * dx + dy * dy <= b.r * b.r * 1.15) {
201|         return b;
202|       }
203|     }
204|     return null;
205|   }
206| 
207|   canvas.style.touchAction = "none";
208|   canvas.addEventListener("pointerdown", (event) => {
209|     event.preventDefault();
210|     if (paused) return;
211|     if (!running) {
212|       running = true;
213|       CARTRIDGE.send("start");
214|       ensureBubbles();
215|       return;
216|     }
217|     const rect = canvas.getBoundingClientRect();
218|     const px = event.clientX - rect.left;
219|     const py = event.clientY - rect.top;
220|     const hit = hitTest(px, py);
221|     if (hit) {
222|       popBubble(hit);
223|     }
224|   });
225| 
226|   function settle() {
227|     for (let i = bubbles.length - 1; i >= 0; i--) {
228|       const b = bubbles[i];
229|       b.y -= b.speed;
230|       b.wobblePhase += 0.02;
231|       b.x += Math.sin(b.wobblePhase) * 0.3;
232|       if (b.y < -b.r - 20) {
233|         bubbles.splice(i, 1);
234|       }
235|     }
236|     if (running) ensureBubbles();
237|     for (let i = pops.length - 1; i >= 0; i--) {
238|       pops[i].t += 1;
239|       if (pops[i].t > 14) pops.splice(i, 1);
240|     }
241|   }
242| 
243|   function drawJitterCircle(cx, cy, r, seed, fillStyle) {
244|     const rnd = seededRand(seed);
245|     const points = 14;
246|     ctx.beginPath();
247|     for (let i = 0; i <= points; i++) {
248|       const angle = (i / points) * Math.PI * 2;
249|       const jitter = (rnd() - 0.5) * 2.2;
250|       const rr = r + jitter;
251|       const x = cx + Math.cos(angle) * rr;
252|       const y = cy + Math.sin(angle) * rr;
253|       if (i === 0) ctx.moveTo(x, y);
254|       else ctx.lineTo(x, y);
255|     }
256|     ctx.closePath();
257|     ctx.fillStyle = fillStyle;
258|     ctx.fill();
259|   }
260| 
261|   function drawBackground() {
262|     ctx.fillStyle = PALETTE.background;
263|     ctx.fillRect(0, 0, W, H);
264|     // subtle layered strips at bottom for paper-cut depth
265|     ctx.save();
266|     ctx.shadowColor = "rgba(61,64,91,0.25)";
267|     ctx.shadowBlur = 6;
268|     ctx.shadowOffsetY = 3;
269|     const rnd = seededRand(777);
270|     ctx.beginPath();
271|     ctx.moveTo(0, H);
272|     for (let x = 0; x <= W; x += 40) {
273|       const jitter = (rnd() - 0.5) * 6;
274|       ctx.lineTo(x, H - 30 + jitter);
275|     }
276|     ctx.lineTo(W, H);
277|     ctx.closePath();
278|     ctx.fillStyle = PALETTE.highlight;
279|     ctx.globalAlpha = 0.5;
280|     ctx.fill();
281|     ctx.globalAlpha = 1;
282|     ctx.restore();
283|   }
284| 
285|   function draw() {
286|     drawBackground();
287| 
288|     if (!running) {
289|       drawTitleScreen();
290|       return;
291|     }
292| 
293|     // bubbles with shadow layer
294|     for (const b of bubbles) {
295|       ctx.save();
296|       ctx.shadowColor = "rgba(61,64,91,0.3)";
297|       ctx.shadowBlur = 6;
298|       ctx.shadowOffsetY = 3;
299|       drawJitterCircle(b.x, b.y, b.r, b.seed, b.color);
300|       ctx.restore();
301| 
302|       // inner highlight circle (paper layer stacked)
303|       ctx.save();
304|       drawJitterCircle(b.x - b.r * 0.25, b.y - b.r * 0.25, b.r * 0.35, b.seed + 5, PALETTE.background);
305|       ctx.globalAlpha = 0.5;
306|       ctx.restore();
307|     }
308| 
309|     // pop animations
310|     for (const p of pops) {
311|       const progress = p.t / 14;
312|       const rr = p.r * (1 + progress * 0.8);
313|       ctx.save();
314|       ctx.globalAlpha = Math.max(0, 1 - progress);
315|       ctx.strokeStyle = PALETTE.accent;
316|       ctx.lineWidth = 2;
317|       ctx.beginPath();
318|       const spikes = 8;
319|       for (let i = 0; i < spikes; i++) {
320|         const angle = (i / spikes) * Math.PI * 2;
321|         const x1 = p.x + Math.cos(angle) * rr * 0.6;
322|         const y1 = p.y + Math.sin(angle) * rr * 0.6;
323|         const x2 = p.x + Math.cos(angle) * rr;
324|         const y2 = p.y + Math.sin(angle) * rr;
325|         ctx.moveTo(x1, y1);
326|         ctx.lineTo(x2, y2);
327|       }
328|       ctx.stroke();
329|       ctx.restore();
330|     }
331|   }
332| 
333|   let hintPhase = 0;
334|   function drawTitleScreen() {
335|     hintPhase += 0.06;
336|     const cx = W / 2;
337|     const cy = H / 2;
338| 
339|     // title plate
340|     ctx.save();
341|     ctx.shadowColor = "rgba(61,64,91,0.3)";
342|     ctx.shadowBlur = 6;
343|     ctx.shadowOffsetY = 3;
344|     const plateW = Math.min(320, W * 0.8);
345|     const plateH = 90;
346|     roundRect(cx - plateW / 2, cy - 120, plateW, plateH, 16);
347|     ctx.fillStyle = PALETTE.layer;
348|     ctx.fill();
349|     ctx.restore();
350| 
351|     ctx.fillStyle = PALETTE.background;
352|     ctx.font = "800 26px sans-serif";
353|     ctx.textAlign = "center";
354|     ctx.textBaseline = "middle";
355|     ctx.fillText("Pop the Bubbles", cx, cy - 75);
356| 
357|     // pulsing hint
358|     const alpha = 0.6 + 0.4 * Math.sin(hintPhase);
359|     ctx.save();
360|     ctx.globalAlpha = alpha;
361|     ctx.fillStyle = PALETTE.accent;
362|     ctx.font = "700 20px sans-serif";
363|     ctx.fillText("Tap to begin", cx, cy + 20);
364|     ctx.restore();
365| 
366|     // decorative bubble samples
367|     drawJitterCircle(cx - 80, cy + 90, 26, 12, PALETTE.highlight);
368|     drawJitterCircle(cx, cy + 100, 32, 34, PALETTE.layer);
369|     drawJitterCircle(cx + 80, cy + 90, 22, 56, PALETTE.accent);
370|   }
371| 
372|   function roundRect(x, y, w, h, r) {
373|     ctx.beginPath();
374|     ctx.moveTo(x + r, y);
375|     ctx.arcTo(x + w, y, x + w, y + h, r);
376|     ctx.arcTo(x + w, y + h, x, y + h, r);
377|     ctx.arcTo(x, y + h, x, y, r);
378|     ctx.arcTo(x, y, x + w, y, r);
379|     ctx.closePath();
380|   }
381| 
382|   function frame() {
383|     if (!paused) settle();
384|     draw();
385|     requestAnimationFrame(frame);
386|   }
387| 
388|   CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
389|   requestAnimationFrame(() => {
390|     draw();
391|     requestAnimationFrame(frame);
392|   });
393| })();
394| </script>
395| </body>
396| </html>
397|

